                __typename: "Task",
                id: 3,
              }],
            }, {
              __typename: "Task",
              id: 2,
              description: "child task 1",
              blockers: [{
                __typename: "Task",
                id: 4,
              }],
            }, {
              __typename: "Task",
              id: 3,
              description: "child task 2",
              blockers: [{
                __typename: "Task",
                id: 4,
              }],
            }, {
              __typename: "Task",
              id: 4,
              description: "grandchild task",
            }],
          },
        },
      });

      expect(cache.extract()).toEqual({
        ROOT_QUERY: {
          __typename: "Query",
          agenda: { __ref: "Agenda:1" },
        },
        "Agenda:1": {
          __typename: "Agenda",
          id: 1,
          tasks: [
            { __ref: "Task:1" },
            { __ref: "Task:2" },
            { __ref: "Task:3" },
            { __ref: "Task:4" },
          ],
        },
        "Task:1": {
          __typename: "Task",
          blockers: [
            { __ref: "Task:2" },
            { __ref: "Task:3" },
          ],
          description: "parent task",
          id: 1,
        },
