          },
        },
        'Todo:{"id":1}': {
          __typename: "Todo",
          id: 1,
          text: "Write more merge tests",
        },
        'Todo:{"id":2}': {
          __typename: "Todo",
          id: 2,
          text: "Write pagination tests",
        },
      });

      cache.writeQuery({
        query,
        data: {
          me: {
