      ROOT_QUERY: {
        __typename: "Query",
        author: {
          __ref: 'Author:{"name":"Virginia Woolf"}',
        },
      },
      'Author:{"name":"Virginia Woolf"}': {
        __typename: "Author",
        name: "Virginia Woolf",
        books: [
          { __ref: 'Book:{"isbn":"1853262390"}' },
          { __ref: 'Book:{"isbn":"9353420717"}' },
          { __ref: 'Book:{"isbn":"0156907399"}' },
        ],
      },
      'Book:{"isbn":"1853262390"}': {
        __typename: "Book",
        isbn: "1853262390",
        title: "Orlando",
        year: 1928,
      },
      'Book:{"isbn":"9353420717"}': {
        __typename: "Book",
        isbn: "9353420717",
        title: "A Room of One's Own",
        year: 1929,
      },
      'Book:{"isbn":"0156907399"}': {
        __typename: "Book",
        isbn: "0156907399",
        title: "To the Lighthouse",
        year: 1927,
      },
    });

    const firstBookQuery = gql`
      query {
        author {
          name
          firstBook {
            title
            year
          }
        }
