          keyFields: ["text"],

          fields: {
            style(_, { args, readField }) {
              const text = readField<string>("text");
              switch (args?.style) {
                case Style.UPPER: return text?.toUpperCase();
                case Style.LOWER: return text?.toLowerCase();
