              return readField<string>({
                fieldName: "style",
                args: { style: Style.LOWER },
              });
            },
            titleCase(_, { readField }) {
              return readField<string>({
                fieldName: "style",
                args: { style: Style.TITLE },
              });
            },
          },
        },
      },
    });

    cache.writeQuery({
      query: gql`query { wordOfTheDay { text } }`,
      data: {
        wordOfTheDay: {
          __typename: "Word",
          text: "inveigle",
        },
      },
    });

    expect(cache.readQuery({
      query: gql`
        query {
          wordOfTheDay {
            upperCase
            lowerCase
            titleCase
          }
        }
      `,
    })).toEqual({
      wordOfTheDay: {
        __typename: "Word",
        upperCase: "INVEIGLE",
        lowerCase: "inveigle",
        titleCase: "Inveigle",
      },
    });
  });

  withWarningSpy(it, "readField warns if explicitly passed undefined `from` option", function () {
    const cache = new InMemoryCache({
      typePolicies: {
        Query: {
          fields: {
            fullNameWithDefaults(_, { readField }) {
              return `${
                readField<string>({
                  fieldName: "firstName",
                })
              } ${
                readField<string>("lastName")
              }`;
            },

            fullNameWithVoids(_, { readField }) {
              return `${
                readField<string>({
                  fieldName: "firstName",
                  // If options.from is explicitly passed but undefined,
                  // readField should not default to reading from the current
                  // object (see issue #8499).
                  from: void 0,
                })
              } ${
                // Likewise for the shorthand version of readField.
                readField<string>("lastName", void 0)
              }`;
            },
          },
        },
      },
    });

    const firstNameLastNameQuery = gql`
      query {
        firstName
        lastName
      }
    `;

    const fullNamesQuery = gql`
      query {
        fullNameWithVoids
        fullNameWithDefaults
      }
    `;

    cache.writeQuery({
      query: firstNameLastNameQuery,
      data: {
        firstName: "Alan",
        lastName: "Turing",
      },
    });

    expect(cache.readQuery({
      query: fullNamesQuery,
    })).toEqual({
      fullNameWithDefaults: "Alan Turing",
      fullNameWithVoids: "undefined undefined",
    });
  });

  it("can return existing object from merge function (issue #6245)", function () {
    const cache = new InMemoryCache({
      typePolicies: {
        Person: {
          fields: {
            currentTask: {
              merge(existing, incoming) {
                // Not a very reasonable merge strategy, but returning
                // existing here triggers issue #6245, persumably because
                // the existing data is frozen.
                return existing || incoming;
              },
            },
          },
        },
        Task: {
          keyFields: false,
        },
      },
    });

    const query = gql`
      query {
        person {
          currentTask {
            __typename
            description
          }
        }
      }
    `;

    cache.writeQuery({
      query,
      data: {
        person: {
          __typename: "Person",
          id: 1234,
          currentTask: {
            __typename: "Task",
            description: "writing tests",
          },
        },
      },
    });

    const snapshot = cache.extract();
    expect(snapshot).toEqual({
      "Person:1234": {
        __typename: "Person",
        id: 1234,
        currentTask: {
          __typename: "Task",
          description: "writing tests",
        },
      },
      ROOT_QUERY: {
        __typename: "Query",
        person: {
          __ref: "Person:1234",
        },
      },
    });

    cache.writeQuery({
      query,
      data: {
        person: {
          __typename: "Person",
          id: 1234,
          currentTask: {
            __typename: "Task",
            description: "polishing knives",
          },
        },
      },
    });

    // Unchanged because the merge function prefers the existing object.
    expect(cache.extract()).toEqual(snapshot);
  });

  it("can alter the root query __typename", function () {
    const cache = new InMemoryCache({
      typePolicies: {
        RootQuery: {
          queryType: true,
        },
      }
    });

    expect(cache.readQuery({
      query: gql`query { __typename }`,
    })).toEqual({
      __typename: "RootQuery",
    });

    const ALL_ITEMS = gql`
      query Items {
        __typename
        items {
          id
          query {
            id
          }
        }
      }
    `;

    function makeItem(id: number) {
      return {
        id,
        query: {
          __typename: "Query",
          id,
        },
      };
    }

    cache.writeQuery({
      query: ALL_ITEMS,
      data: {
        __typename: "RootQuery",
        items: [
          makeItem(0),
          makeItem(1),
          makeItem(2),
          makeItem(3),
        ],
      },
    });

    expect(cache.extract()).toMatchSnapshot();

    expect(cache.readQuery({
      query: ALL_ITEMS,
    })).toEqual({
      __typename: "RootQuery",
      items: [
        makeItem(0),
        makeItem(1),
        makeItem(2),
        makeItem(3),
      ],
    });
  });

  it("can configure {query,mutation,subscription}Type:true", () => {
    const cache = new InMemoryCache({
      typePolicies: {
        RootQuery: {
          queryType: true,
        },
        RootMutation: {
          mutationType: true,
        },
        RootSubscription: {
          subscriptionType: true,
        },
      }
    });

    expect(cache.readQuery({
      query: gql`query { __typename }`,
    })).toEqual({
      __typename: "RootQuery",
    });

    expect(cache.readFragment({
      id: "ROOT_MUTATION",
      fragment: gql`
        fragment MutationTypename on RootMutation {
          __typename
        }
      `,
    })).toEqual({
      __typename: "RootMutation",
    });

    expect(cache.readFragment({
      id: "ROOT_SUBSCRIPTION",
      fragment: gql`
        fragment SubscriptionTypename on RootSubscription {
          __typename
        }
      `,
    })).toEqual({
      __typename: "RootSubscription",
    });
  });
});

